UPDATE `locales_quest` SET `title_loc3`='Der Weg des Jägers',`details_loc3`='Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.$B$BIhr müsst Thotar in Klingenhügel besuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.',`objectives_loc3`='Sprecht mit Thotar in Klingenhügel in Durotar.',`offerrewardtext_loc3`='Ja, es ist Zeit, Euer Training zu beginnen.' WHERE `entry`=6068;
