UPDATE `locales_quest` SET `title_loc3`='Der Weg des Jägers',`details_loc3`='Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.$B$BIhr müsst Grif Wildherz in Kharanos aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.',`objectives_loc3`='Sprecht mit Grif Wildherz in Kharanos in Dun Morogh.',`offerrewardtext_loc3`='Ja, ich glaube, Ihr seid bereit...' WHERE `entry`=6074;
