UPDATE `locales_quest` SET `title_loc3`='Jubjubs Nachwuchs',`offerrewardtext_loc3`='Vielen Dank, $N. Hier ist Euer Ei! Es wird noch etwas dauern bevor es ausgebrütet werden kann, doch wenn es soweit ist habt Ihr ein großartiges Haustier!' WHERE `entry`=7946;
UPDATE `locales_quest` SET `title_loc3`='Verdammte Kaninchen!',`details_loc3`='Diese Hasen vermehren sich wie... die Karnickel!$B$BZieht los und erlegt ein paar für mich!' WHERE `entry`=7961;
UPDATE `locales_quest` SET `title_loc3`='Kaninchenfelle',`details_loc3`='Ich brauche einige LeCraft-Kaninchenfelle. Besorgt mir einige von den LeCrafty-Kaninchen.$B$BEine wichtige Aufgabe!',`objectives_loc3`='Bringt 3 LeCraft-Kaninchenfelle zu Jon LeCraft.' WHERE `entry`=7962;
