UPDATE `locales_quest` SET `title_loc3`='Der Schwur des Weisen',`details_loc3`='Ihr habt das Versprechen, das Ihr uns gegeben habt, gehalten, $N. Und dafür steht Euch die gebührende Anerkennung zu.$B$BWährend Ihr Euch weiter mit den vergangenen Ereignissen am Berg Hyjal vertraut macht, werde ich tiefer in die Macht in Eurem Ring eintauchen. Es wird nicht mehr lange dauern, bis er seine volle Kraft erlangt hat.',`objectives_loc3`='Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen respektvollen Ruf bei den Wächtern der Sande erlangt habt.' WHERE `entry`=10468;
UPDATE `locales_quest` SET `title_loc3`='Der Schwur des Bewahrers',`details_loc3`='Ihr habt das Versprechen, das Ihr uns gegeben habt, gehalten, $N. Und dafür steht Euch die gebührende Anerkennung zu.$B$BWährend Ihr Euch weiter mit den vergangenen Ereignissen am Berg Hyjal vertraut macht, werde ich tiefer in die Macht in Eurem Ring eintauchen. Es wird nicht mehr lange dauern, bis er seine volle Kraft erlangt hat.',`objectives_loc3`='Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen respektvollen Ruf bei den Wächtern der Sande erlangt habt.' WHERE `entry`=10469;
