UPDATE `locales_quest` SET `title_loc3`='Aufstieg eines Champions',`details_loc3`='Herzlichen Glückwunsch, $N. Ihr habt viele Kampfesarten gemeistert und all die Herausforderungen bewältigt, denen Ihr Euch gestellt habt. Ihr seid zweifellos dazu bereit, gegen die besten Krieger des Turniers anzutreten - den Champions der Hauptstädte.$B$BJustiziarin Mariel Treuherz hat darum gebeten, mit Euch zu sprechen, $N, und Euch offiziell beim großen Arenakampf der Champions anzumelden.',`objectives_loc3`='Sprecht mit Justiziarin Mariel Treuherz beim Argentumturnierplatz.' WHERE `entry`=13732;
