UPDATE `locales_quest` SET `title_loc3`='Das Feuer erwidern',`details_loc3`='Die meisten Feuer sind unter Kontrolle, aber wir müssen etwas gegen diese Windreiter unternehmen!$B$BSchnell, $N, Ihr müsst in eine unserer Glevenschleudern klettern und das Feuer erwidern!',`objectives_loc3`='Verwendet eine Schleuder von Astranaar, um 15 von Höllschreis Vandalen und ihre Wachwindreiter abzuschießen.' WHERE `entry`=13853;
