UPDATE `locales_quest` SET `title_loc3`='Ruf zu den Waffen: Kriegshymnenschlucht',`details_loc3`='Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.',`objectives_loc3`='Gewinnt eine Schlacht in der Kriegshymnenschlucht und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.' WHERE `entry`=24225;
