UPDATE `locales_quest` SET `details_loc3`='Die Zwergenfrau Donova Schneeweh ist mit dem Furbolgs der Holzschlundfeste befreundet.$B$BWir handeln mit Feuerwasser.$B$BSie ist bei den Frostfeuerquellen im Westen, wenn Ihr durch unsere Höhle geht.$B$BSie braucht Unterstützung beim Verprügeln der Furbolgs der Winterfelle. Vielleicht könnt Ihr ihr helfen.',`objectives_loc3`='Meldet Euch bei Donova Schneeweh an den Frostfeuerquellen in Winterquell.' WHERE `entry`=28768;
